/*
 * Standalone model of the hfsplus_lookup() hardlink-detection guard ordering.
 * This is NOT a build of fs/hfsplus/dir.c; it isolates the short-circuit
 * semantics of the exact expression changed by the candidate, to compare the
 * vulnerable ordering with the fixed ordering when hidden_dir is NULL.
 *
 * old: (cmp_hidden || cmp_root) && hidden_dir   -> dereferences hidden_dir first
 * new: hidden_dir && (cmp_hidden || cmp_root)   -> NULL-safe short-circuit
 */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>

struct inode { uint32_t create_date; };
struct sb_info { struct inode *hidden_dir; };

static inline struct inode *HFSPLUS_I(struct inode *inode) { return inode; }

static int old_cond(uint32_t cd, struct sb_info *sbi, struct inode *root)
{
	return (cd == HFSPLUS_I(sbi->hidden_dir)->create_date ||
		cd == HFSPLUS_I(root)->create_date) && sbi->hidden_dir;
}

static int new_cond(uint32_t cd, struct sb_info *sbi, struct inode *root)
{
	return sbi->hidden_dir &&
	       (cd == HFSPLUS_I(sbi->hidden_dir)->create_date ||
		cd == HFSPLUS_I(root)->create_date);
}

static int run_child(int which, uint32_t cd, struct sb_info *sbi, struct inode *root)
{
	pid_t pid = fork();
	if (pid == 0) {
		int r = which ? new_cond(cd, sbi, root) : old_cond(cd, sbi, root);
		_exit(r == 0 ? 0 : 2);
	}
	int status;
	waitpid(pid, &status, 0);
	if (WIFSIGNALED(status))
		return -WTERMSIG(status);
	if (WIFEXITED(status))
		return WEXITSTATUS(status);
	return -99;
}

int main(void)
{
	struct inode root = { .create_date = 100 };
	struct sb_info nul = { .hidden_dir = NULL };
	struct sb_info have = { .hidden_dir = &(struct inode){ .create_date = 100 } };
	struct inode other = { .create_date = 999 };
	struct sb_info have2 = { .hidden_dir = &other };
	int r;

	printf("negative path (hidden_dir == NULL, catalog claims hardlink, cd==root date):\n");
	r = run_child(0, 100, &nul, &root);
	printf("  old_cond -> %s (%d)\n", r < 0 ? "SIGNAL/CRASH" : "no-branch", r);
	if (r >= 0) { printf("MODEL FAILED: old ordering did not crash\n"); return 1; }
	r = run_child(1, 100, &nul, &root);
	printf("  new_cond -> %s (%d)\n", r < 0 ? "SIGNAL/CRASH" : "no-branch", r);
	if (r != 0) { printf("MODEL FAILED: new ordering did not safely return false\n"); return 1; }

	printf("positive path (hidden_dir present, cd matches hidden_dir):\n");
	r = run_child(1, 100, &have, &root);
	printf("  new_cond -> %s (%d)\n", r < 0 ? "SIGNAL/CRASH" : "branch", r);
	if (r != 2) { printf("MODEL FAILED: new ordering lost hardlink detection\n"); return 1; }

	printf("positive path (hidden_dir present, cd matches root date only):\n");
	r = run_child(1, 100, &have2, &root);
	printf("  new_cond -> %s (%d)\n", r < 0 ? "SIGNAL/CRASH" : "branch", r);
	if (r != 2) { printf("MODEL FAILED: root-date comparison lost\n"); return 1; }

	printf("negative path II (hidden_dir present, cd matches neither):\n");
	have2.hidden_dir->create_date = 555;
	r = run_child(1, 100, &have2, &root);
	printf("  new_cond -> %s (%d)\n", r < 0 ? "SIGNAL/CRASH" : "no-branch", r);
	if (r != 0) { printf("MODEL FAILED: non-matching date took branch\n"); return 1; }

	printf("ALL CHECKS PASSED\n");
	return 0;
}

